    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'A 22-year-old female lead singer presents with progressive hoarseness, vocal fatigue, and loss of her upper vocal range over the last 6 months. Laryngoscopy reveals bilateral, symmetric, small, firm swellings on the true vocal folds. What is the most likely diagnosis?', '["Vocal fold polyps", "Reinke''s edema", "Vocal fold nodules", "Vocal fold cysts", "Laryngeal papillomatosis"]'::jsonb, 2, 'Bilateral, symmetric swellings in a young patient with a history of vocal abuse (singing, yelling) are classic for vocal fold nodules (singer''s nodes).'),
    (v_topic_id, 'Where on the vocal folds do nodules characteristically form?', '["At the anterior commissure", "At the junction of the anterior one-third and posterior two-thirds", "At the vocal processes of the arytenoids", "On the false vocal folds", "In the subglottis"]'::jsonb, 1, 'Nodules form at the junction of the anterior 1/3 and posterior 2/3 of the membranous vocal fold, because this is the point of maximal amplitude and strongest mechanical collision force during phonation.'),
    (v_topic_id, 'What is the underlying pathophysiology of vocal fold nodules?', '["Viral infection of the mucosa", "Chronic phonotrauma (vocal abuse) leading to localized mechanical stress, edema, and subsequent fibrosis/hyalinization", "Autoimmune destruction of cartilage", "Acid reflux burning the anterior cords", "Congenital malformation"]'::jsonb, 1, 'Nodules are essentially "calluses" of the vocal folds, formed by repetitive mechanical trauma over a long period.'),
    (v_topic_id, 'What is the universally accepted first-line, standard-of-care treatment for vocal fold nodules?', '["Immediate surgical excision with a laser", "Total voice rest for 6 months", "Voice therapy (Speech-Language Pathology) to correct underlying vocal habits", "Proton pump inhibitors", "Botox injections"]'::jsonb, 2, 'Nodules are a behavioral problem. Surgery is rarely indicated and only considered if strict, prolonged voice therapy fails. If the behavior isn''t corrected, excised nodules will simply recur.'),
    (v_topic_id, 'A 45-year-old male football coach presents with constant hoarseness. He vividly remembers losing his voice suddenly while screaming at a referee during a game 2 months ago. Laryngoscopy reveals a unilateral, broad-based, hemorrhagic, fluid-filled mass on the right vocal fold. What is the diagnosis?', '["Vocal fold nodule", "Vocal fold polyp", "Reinke''s edema", "Granuloma", "Squamous cell carcinoma"]'::jsonb, 1, 'A vocal fold polyp is typically unilateral and often arises from a single, severe episode of phonotrauma (like screaming), leading to localized submucosal bleeding and edema that organizes into a polyp.'),
    (v_topic_id, 'In which anatomical layer of the vocal fold do benign lesions like polyps, nodules, and Reinke''s edema typically develop?', '["The stratified squamous epithelium", "The superficial lamina propria (Reinke''s space)", "The intermediate lamina propria", "The deep lamina propria", "The vocalis muscle"]'::jsonb, 1, 'Most benign phonotraumatic lesions occur in Reinke''s space (the superficial lamina propria), which is the loose, gelatinous layer that actively vibrates during speech.'),
    (v_topic_id, 'If a mature, fibrotic vocal fold polyp fails to improve with voice therapy, what is the appropriate management?', '["Radiation therapy", "Phonomicrosurgery (microlaryngoscopy with conservative cold-instrument excision) to restore a straight vocal edge", "Total laryngectomy", "Tracheostomy", "Observation indefinitely"]'::jsonb, 1, 'While voice therapy helps correct underlying habits, a large or organized polyp usually requires careful surgical excision, preserving as much normal mucosa as possible.'),
    (v_topic_id, 'A 60-year-old female with a 40-pack-year smoking history presents with a progressively deep, very low-pitched, "gravelly" and masculine-sounding voice. Laryngoscopy reveals bilateral, massive, "water-bag" or balloon-like swelling along the entire length of both true vocal folds. What is the diagnosis?', '["Vocal fold nodules", "Laryngeal cancer", "Reinke''s edema (Polypoid corditis)", "Laryngocele", "Vocal fold paralysis"]'::jsonb, 2, 'Reinke''s edema is characterized by massive accumulation of gelatinous fluid in the superficial lamina propria. It is almost exclusively seen in heavy, chronic smokers, often middle-aged women.'),
    (v_topic_id, 'Why does a patient with severe Reinke''s edema develop a remarkably low-pitched, masculine voice?', '["The vocal cords are paralyzed open", "The massive fluid accumulation increases the mass of the vocal folds, significantly decreasing their fundamental frequency of vibration", "Testosterone levels increase with smoking", "The vocal cords shorten", "The epiglottis covers the airway"]'::jsonb, 1, 'In acoustics, increased mass leads to slower vibration. The heavy, fluid-filled vocal folds vibrate at a much lower frequency, drastically lowering the pitch of the voice.'),
    (v_topic_id, 'What is the absolute most critical first step in the management of Reinke''s edema?', '["Surgical stripping of the vocal folds", "Absolute smoking cessation", "Voice therapy", "Proton pump inhibitors", "Inhaled steroids"]'::jsonb, 1, 'Smoking cessation is mandatory. Often, stopping smoking will halt progression or partially reverse the edema. If surgery is performed while the patient continues to smoke, the edema will rapidly recur.'),
    (v_topic_id, 'If surgery is required for airway obstruction in severe Reinke''s edema, what surgical technique is generally preferred?', '["Laser vaporization of the entire vocal fold", "Total laryngectomy", "An incision on the superior surface of the vocal fold to suction out the myxoid fluid, followed by trimming excess mucosa while preserving the free vibrating edge", "Botox injection", "Vocal cord stripping (removing all mucosa)"]'::jsonb, 2, 'Phonomicrosurgery aims to evacuate the fluid and re-drape the mucosa to recreate a sharp, straight vibrating edge. "Stripping" the cords is obsolete and causes severe, permanent scarring.'),
    (v_topic_id, 'A 50-year-old male was recently discharged from the ICU after a 10-day intubation for pneumonia. He now complains of hoarseness and a sensation of a "lump" stuck in his throat. Laryngoscopy reveals bilateral, pale, lobulated, fleshy masses on the vocal processes of the arytenoids. What is the diagnosis?', '["Squamous cell carcinoma", "Intubation granulomas (contact granulomas)", "Vocal fold nodules", "Vocal fold cysts", "Reinke''s edema"]'::jsonb, 1, 'Intubation granulomas result from the endotracheal tube resting against and eroding the thin mucosa over the arytenoid cartilages, causing ulceration and subsequent granuloma formation during healing.'),
    (v_topic_id, 'Where in the larynx do contact granulomas and intubation granulomas characteristically form?', '["The anterior commissure", "The middle third of the membranous vocal fold", "The posterior glottis, specifically on the vocal processes of the arytenoid cartilages", "The false vocal folds", "The epiglottis"]'::jsonb, 2, 'They form posteriorly because this is where the cartilaginous vocal processes firmly strike each other during forceful phonation/throat clearing, and where an ET tube rests.'),
    (v_topic_id, 'In a patient without a history of intubation, what are the two main contributing factors to the development of a contact granuloma?', '["Smoking and alcohol", "Laryngopharyngeal Reflux (LPR) and chronic throat clearing/forceful phonation", "Viral URI and allergies", "Asthma and inhaler use", "Autoimmune disease and steroids"]'::jsonb, 1, 'Acid reflux bathes the posterior larynx, inflaming the mucosa, while chronic throat clearing (a common symptom of LPR) repeatedly traumatizes the inflamed arytenoids, driving granuloma formation.'),
    (v_topic_id, 'What is the recommended initial management for contact granulomas?', '["Aggressive surgical excision with a laser", "Total laryngectomy", "Conservative management with aggressive anti-reflux medication (PPIs), voice therapy, and observation", "Radiation therapy", "Antibiotics"]'::jsonb, 2, 'Surgery has a very high recurrence rate for granulomas because the surgical trauma itself can stimulate more granuloma formation. Most resolve over several months with aggressive medical and behavioral management.'),
    (v_topic_id, 'A 30-year-old female presents with persistent hoarseness. Laryngoscopy reveals a unilateral, submucosal, yellowish, opaque swelling deep within the right vocal fold. The mucosa over it is intact but stretched. During stroboscopy, the mucosal wave is absent over the lesion. What is the most likely diagnosis?', '["Vocal fold nodule", "Reinke''s edema", "Vocal fold cyst (epidermoid or retention)", "Contact granuloma", "Squamous cell carcinoma"]'::jsonb, 2, 'Vocal fold cysts are encapsulated, fluid-filled or keratin-filled lesions deep in the lamina propria. They stretch the overlying mucosa and eliminate the mucosal wave, causing stiffness and hoarseness.'),
    (v_topic_id, 'How does a mucous retention cyst differ from an epidermoid cyst in the vocal fold?', '["Retention cysts are cancerous; epidermoid cysts are benign", "Retention cysts arise from obstructed mucous gland ducts; epidermoid cysts arise from trapped squamous epithelium (often from trauma or congenital)", "Retention cysts are solid; epidermoid cysts are fluid", "Retention cysts occur in the subglottis; epidermoid cysts on the epiglottis", "They are entirely identical"]'::jsonb, 1, 'Both present as submucosal masses, but retention cysts are lined by glandular epithelium and filled with mucus, while epidermoid cysts are lined by squamous epithelium and filled with keratin debris.'),
    (v_topic_id, 'What is the treatment of choice for a symptomatic vocal fold cyst?', '["Voice therapy only", "Surgical microflap excision to enucleate the intact cyst from the lamina propria", "Laser vaporization of the entire cord", "Botox injection", "Antibiotics"]'::jsonb, 1, 'Unlike nodules, cysts rarely resolve with voice therapy. They require meticulous surgical enucleation (peeling the cyst out whole) while preserving the overlying mucosa.'),
    (v_topic_id, 'A 28-year-old opera singer experiences a sudden, sharp pain in her neck and immediate loss of voice while hitting a high note during a performance. Laryngoscopy reveals a dark red, blood-filled appearance of the entire right true vocal fold. What is the diagnosis?', '["Acute vocal fold hemorrhage", "Ruptured vocal fold cyst", "Laryngeal cancer", "Acute viral laryngitis", "Laryngeal fracture"]'::jsonb, 0, 'Acute vocal fold hemorrhage occurs when the extreme shear stress of loud/high phonation ruptures a microvascular vessel in Reinke''s space, instantly filling the vocal fold with blood and stiffening it.'),
    (v_topic_id, 'What is the most critical, non-negotiable management step for an acute vocal fold hemorrhage?', '["Whispering", "Singing through the pain", "Absolute, strict voice rest for 7-10 days", "Steroid injections", "Emergency surgery to drain the blood"]'::jsonb, 2, 'Continuing to phonate on a hemorrhaged fold can cause the blood to organize into a hematoma and fibrose, leading to permanent scarring and lifelong dysphonia. Strict rest allows the blood to resorb safely.'),
    (v_topic_id, 'A patient with an acute vocal fold hemorrhage should be immediately advised to discontinue which type of medication, if applicable?', '["Acetaminophen", "Aspirin, NSAIDs, or any blood thinners", "Antibiotics", "Proton pump inhibitors", "Antihistamines"]'::jsonb, 1, 'Blood thinners inhibit platelet function and can exacerbate or prolong the bleeding into the vocal fold.'),
    (v_topic_id, 'A 4-year-old boy presents with a 2-year history of chronic hoarseness and recent onset of mild stridor. Awake flexible laryngoscopy reveals multiple, irregular, pink, "cauliflower-like" exophytic lesions covering the true and false vocal folds. What is the diagnosis?', '["Vocal fold nodules", "Squamous cell carcinoma", "Recurrent Respiratory Papillomatosis (RRP)", "Croup", "Laryngomalacia"]'::jsonb, 2, 'Multiple exophytic, wart-like lesions in a child''s airway are the hallmark of Juvenile-onset Recurrent Respiratory Papillomatosis (JoRRP).'),
    (v_topic_id, 'What is the infectious etiology of Recurrent Respiratory Papillomatosis (RRP)?', '["Epstein-Barr Virus (EBV)", "Human Papillomavirus (HPV), typically types 6 and 11", "Herpes Simplex Virus (HSV)", "Cytomegalovirus (CMV)", "Adenovirus"]'::jsonb, 1, 'HPV 6 and 11 are the causative agents. In children, the virus is usually acquired via vertical transmission from an infected mother during vaginal birth.'),
    (v_topic_id, 'What is the hallmark clinical course of Juvenile-onset RRP?', '["It resolves completely after a single dose of antibiotics", "It never recurs after one surgical excision", "It causes rapid death from metastasis", "Relentless, frequent recurrences requiring multiple surgical procedures (sometimes dozens) to maintain the airway and voice", "It transforms into melanoma"]'::jsonb, 3, 'RRP is notoriously stubborn. The virus lives latently in normal-appearing adjacent mucosa, so surgical removal of the visible warts does not cure the disease, leading to frequent recurrences.'),
    (v_topic_id, 'When surgically managing RRP in the larynx, what is the primary goal?', '["Curative wide-margin resection of the entire larynx", "Debulking the papillomas to preserve a safe airway and functional voice, while avoiding damage to the underlying vocal ligament", "Complete eradication of the virus using a scalpel", "Total vocal cord stripping", "Radiation therapy"]'::jsonb, 1, 'Because it is not cancer and recurs frequently, the goal is airway maintenance. Aggressive surgery that damages the vocal ligament or anterior commissure will cause permanent laryngeal scarring and a "crippled" larynx.'),
    (v_topic_id, 'Which surgical instrument is commonly used to accurately "shave" off RRP lesions while suctioning the debris to prevent distal airway seeding?', '["A large scalpel", "A microdebrider or specific lasers (e.g., CO2, KTP)", "A curette", "A rigid bronchoscope alone", "Electrocautery"]'::jsonb, 1, 'The laryngeal microdebrider is excellent for shaving papillomas off the mucosal surface safely. Lasers (like KTP which targets blood vessels) are also widely used.'),
    (v_topic_id, 'A 45-year-old male presents with hoarseness. Laryngoscopy reveals a small, reactive mucosal thickening on the LEFT vocal fold, exactly opposite to a large, firm polyp on the RIGHT vocal fold. What is this secondary lesion called?', '["A cancerous metastasis", "A contact lesion (or reactive nodule/polyp)", "A laryngocele", "A papilloma", "A cyst"]'::jsonb, 1, 'A reactive or contact lesion forms on the contralateral vocal fold due to the repetitive, localized mechanical pounding from the primary lesion on the opposite side.'),
    (v_topic_id, 'What is a "sulcus vocalis"?', '["A large polyp on the vocal fold", "A congenital or acquired linear groove/furrow along the medial edge of the vocal fold that tethers the mucosa to the underlying ligament", "A cancerous ulcer", "A type of papilloma", "A vocal fold paralysis"]'::jsonb, 1, 'Sulcus vocalis is a structural groove that causes severe stiffness of the mucosal cover, resulting in a breathy, hoarse voice. It is notoriously difficult to treat surgically.'),
    (v_topic_id, 'During stroboscopy, the "mucosal wave" is evaluated. What does the presence of a normal, symmetric mucosal wave indicate?', '["The patient has cancer", "The superficial lamina propria (Reinke''s space) is pliable, healthy, and freely sliding over the deeper vocal ligament", "The vocal cords are paralyzed", "The patient has vocal fold nodules", "The vocal cords are tethered by scar"]'::jsonb, 1, 'The mucosal wave relies on a healthy, loose superficial lamina propria. A lesion that tethers the mucosa to the ligament (like a cyst or scar) will eliminate the mucosal wave in that specific area.'),
    (v_topic_id, 'A patient is diagnosed with severe vocal fold scarring after a poorly performed surgery to remove a polyp. What is the typical voice outcome in severe vocal fold scarring?', '["A perfectly normal voice", "A permanently stiff, breathy, and severely dysphonic voice due to loss of the mucosal wave", "An extremely deep voice", "A loud, booming voice", "A high-pitched squeak"]'::jsonb, 1, 'Scarring replaces the loose lamina propria with dense collagen, tethering the mucosa to the ligament. The fold cannot vibrate properly, devastating the voice.'),
    (v_topic_id, 'What is the primary optical principle behind Laryngeal Videostroboscopy?', '["It uses X-rays to see through tissue", "It flashes a light at slightly different frequencies than the vocal fold vibration to create a slow-motion optical illusion of the mucosal wave", "It uses ultrasound waves", "It uses an MRI magnet", "It provides a static, frozen image only"]'::jsonb, 1, 'Because the vocal folds vibrate too fast for the human eye to see (100-300 Hz), stroboscopy flashes light asynchronously to piece together images from different cycles, creating a slow-motion video of the vibration.'),
    (v_topic_id, 'A 55-year-old male presents with hoarseness. Endoscopy shows a unilateral, broad-based swelling of the vocal fold. Stroboscopy reveals that the mucosal wave is completely ABSENT over the mass, and the mass appears rigid. What is the most concerning diagnosis that must be ruled out?', '["Vocal fold nodule", "Reinke''s edema", "Invasive squamous cell carcinoma", "Vocal fold polyp", "Contact granuloma"]'::jsonb, 2, 'Benign lesions (like polyps) usually preserve some mucosal wave. An absent mucosal wave over a solid mass strongly suggests the mass has invaded deeply into the vocalis muscle or ligament, a hallmark of invasive carcinoma.'),
    (v_topic_id, 'What is the definition of "Phonotrauma"?', '["A penetrating injury to the neck", "Behaviors that cause mechanical stress and injury to the vocal folds, such as yelling, throat clearing, or poor singing technique", "A viral infection of the vocal cords", "Paralysis of the vocal cords", "Acid reflux burning the vocal cords"]'::jsonb, 1, 'Phonotrauma (formerly called vocal abuse/misuse) is the mechanical etiology behind nodules, polyps, and hemorrhages.'),
    (v_topic_id, 'Which of the following is considered a primary component of "Vocal Hygiene" taught by a Speech-Language Pathologist?', '["Drinking caffeine to stimulate the cords", "Whispering constantly", "Frequent, forceful throat clearing", "Adequate systemic hydration and avoiding irritating behaviors (yelling, smoking, excess caffeine/alcohol)", "Using steroid inhalers daily"]'::jsonb, 3, 'Vocal hygiene involves optimizing the laryngeal environment. Hydration is key because well-hydrated vocal folds require less lung pressure to vibrate and sustain less impact trauma.'),
    (v_topic_id, 'A singer presents with vocal fatigue. The SLP diagnoses "Muscle Tension Dysphonia" (MTD). What does this mean?', '["The vocal cords are paralyzed", "There is a tumor on the vocal cord", "Excessive, unbalanced tension in the paralaryngeal and extrinsic neck muscles is causing vocal strain, despite structurally normal vocal folds", "The patient has a systemic muscle disease like ALS", "The patient has acid reflux"]'::jsonb, 2, 'MTD is a functional voice disorder where poor technique and excess muscle tension cause hoarseness and fatigue. The larynx itself is structurally normal. It is treated with voice therapy.'),
    (v_topic_id, 'During phonomicrosurgery, the surgeon uses a "microflap" technique to remove a vocal fold cyst. What is the primary advantage of this technique?', '["It removes the entire vocal fold", "It allows the surgeon to elevate the normal mucosa, remove the cyst, and lay the healthy mucosa back down, minimizing scarring and preserving the vibrating edge", "It uses a massive laser to burn the cyst", "It requires a tracheostomy", "It removes the vocal ligament"]'::jsonb, 1, 'The microflap technique is the gold standard for preserving the precious superficial lamina propria and the mucosal cover, ensuring optimal post-operative voice quality.'),
    (v_topic_id, 'What is the difference between a sessile and a pedunculated vocal fold polyp?', '["Sessile is cancerous, pedunculated is benign", "Sessile has a broad base attaching it to the vocal fold; pedunculated hangs from a narrow stalk", "Sessile is fluid-filled, pedunculated is solid", "Sessile is on the false cord, pedunculated is on the true cord", "There is no difference"]'::jsonb, 1, 'These terms describe the morphology. Pedunculated polyps can sometimes flop in and out of the glottis during breathing, causing intermittent voice changes or stridor.'),
    (v_topic_id, 'A 10-year-old child presents with chronic hoarseness. Endoscopy shows small, bilateral nodules on the vocal folds. What is the most appropriate management?', '["Immediate laser excision", "Botox injection", "Voice therapy and counseling for the child and parents to reduce yelling and vocal strain", "Systemic steroids", "Total laryngectomy"]'::jsonb, 2, 'Vocal nodules in children (often called "screamer''s nodes") are very common and almost always resolve with behavioral modification (voice therapy) and age. Surgery is contraindicated in children for nodules.'),
    (v_topic_id, 'Which benign laryngeal lesion is caused by a blockage of the ducts of the mucous glands located in the laryngeal ventricle or false vocal folds?', '["Vocal fold nodule", "Reinke''s edema", "Mucous retention cyst", "Epidermoid cyst", "Contact granuloma"]'::jsonb, 2, 'Retention cysts occur where mucous glands are plentiful (ventricle, false cords, subglottis). The true vocal folds themselves have very few, if any, mucous glands.'),
    (v_topic_id, 'A patient presents with a very breathy voice. Endoscopy shows that when they attempt to speak, the vocal folds come together anteriorly and posteriorly, but there is a spindle-shaped gap in the middle. What is this gap called?', '["Glottic web", "Glottic insufficiency (or incompetence)", "Subglottic stenosis", "Laryngomalacia", "Pachydermia"]'::jsonb, 1, 'Glottic insufficiency means the vocal folds cannot close completely. This allows air to escape unvoiced, resulting in a weak, breathy voice. It can be caused by bowing, paralysis, or a mass propping the cords apart.'),
    (v_topic_id, 'A patient with a large unilateral vocal fold polyp has a breathy voice. Why?', '["The polyp paralyzes the nerve", "The bulk of the polyp props the vocal folds apart, preventing complete glottic closure along the rest of the vocal fold (glottic insufficiency)", "The polyp absorbs sound", "The polyp causes asthma", "The polyp destroys the cartilage"]'::jsonb, 1, 'A mass on one cord prevents the other cord from meeting it squarely, leaving gaps where air escapes.'),
    (v_topic_id, 'What is the primary role of the false vocal folds (vestibular folds) during normal phonation?', '["They vibrate to produce high pitches", "They vibrate to produce low pitches", "They do NOT play a primary role in normal phonation; they are primarily protective and help close the airway tightly during swallowing and effort closure", "They control the movement of the epiglottis", "They produce saliva"]'::jsonb, 2, 'The false vocal folds should remain relaxed during normal speech. If a patient uses their false cords to speak (ventricular phonation), it sounds very rough and strained, usually compensating for true vocal cord dysfunction.'),
    (v_topic_id, 'A patient is diagnosed with "Ventricular Phonation" (false cord phonation). What does their voice typically sound like?', '["High, pure, and clear", "Deep, rough, strained, and harsh", "A completely silent whisper", "A normal voice", "A nasal voice"]'::jsonb, 1, 'Because the false cords are thick and lack the fine vibrating structure of Reinke''s space, using them to phonate produces a very rough, strained, low-pitched voice.'),
    (v_topic_id, 'In the context of laryngeal surgery, what does the term "anterior web" refer to, and why is it feared?', '["A spider web in the airway", "A scar that forms across the anterior commissure fusing the vocal folds together; it severely worsens the voice and is very difficult to treat", "A normal anatomical structure", "A type of cancer", "A cyst"]'::jsonb, 1, 'If a surgeon operates too aggressively at the anterior commissure (where the cords meet), the raw surfaces can scar together, forming an iatrogenic web that blunts the vibrating edge and shortens the cords.'),
    (v_topic_id, 'To prevent an iatrogenic anterior web, what surgical rule must be followed when removing bilateral lesions (like nodules) near the anterior commissure?', '["Remove both at the exact same time", "Never operate on the larynx", "Avoid creating opposing raw, denuded mucosal surfaces at the anterior commissure at the same time", "Use a larger laser", "Remove the cartilage"]'::jsonb, 2, 'If opposing raw surfaces are created, they will heal to each other, forming a web. Surgeons often stage the procedures or leave a strip of intact mucosa anteriorly to prevent this.'),
    (v_topic_id, 'A 35-year-old teacher presents with vocal fatigue. Stroboscopy shows no masses, but the vocal folds appear slightly bowed, and there is anterior-posterior squeezing of the supraglottis during speech. What is the most likely diagnosis?', '["Muscle Tension Dysphonia (MTD)", "Vocal fold polyp", "Squamous cell carcinoma", "Vocal fold paralysis", "Laryngomalacia"]'::jsonb, 0, 'Supraglottic squeeze (hyperfunction) is the classic endoscopic hallmark of Muscle Tension Dysphonia, where the patient uses extrinsic neck muscles to force phonation.'),
    (v_topic_id, 'What is the primary treatment for Muscle Tension Dysphonia?', '["Botox injections", "Surgical excision of the false cords", "Voice therapy focusing on laryngeal relaxation, proper breath support, and resonance", "Total laryngectomy", "Proton pump inhibitors"]'::jsonb, 2, 'Voice therapy (often using techniques like circumlaryngeal massage and resonant voice therapy) effectively "unloads" the tension and restores normal functional voicing.'),
    (v_topic_id, 'Which of the following describes a "varix" on a vocal fold?', '["A malignant tumor", "A prominent, enlarged, tortuous superficial blood vessel that increases the risk of vocal fold hemorrhage", "A deep cyst", "A paralyzed nerve", "A fungal plaque"]'::jsonb, 1, 'A varix or ectasia is an enlarged capillary on the surface of the vocal fold, often caused by chronic phonotrauma. It acts as a weak point that can rupture and cause a hemorrhage.'),
    (v_topic_id, 'If a vocal fold varix causes recurrent hemorrhages in a professional singer, what is a common treatment option?', '["Total laryngectomy", "Careful laser ablation (e.g., with KTP or pulsed-dye laser) of the vessel to prevent future bleeding, while preserving the surrounding mucosa", "Vocal cord stripping", "Botox injection", "Observation only"]'::jsonb, 1, 'Lasers that target hemoglobin (KTP, PDL) can precisely coagulate the offending vessel without damaging the delicate lamina propria, preventing career-threatening recurrent hemorrhages.'),
    (v_topic_id, 'A 40-year-old male presents with hoarseness. He works in a noisy factory and yells over machinery all day. Laryngoscopy shows bilateral, thickened, white, firm plaques on the middle third of the vocal cords. What is this specific phonotraumatic lesion called?', '["Vocal fold cyst", "Macula flava", "Vocal fold nodules", "Vocal fold polyps", "Reinke''s edema"]'::jsonb, 2, 'While leukoplakia must be ruled out, firm, bilateral, mid-membranous lesions in a classic vocal abuser are vocal fold nodules. The thickening is essentially hyperkeratosis in response to trauma.')
